export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-35\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 35,\n    \"title\": \"外儲說右下\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 17,\n    \"passageIds\": [\n      \"han-fei-zi_ch-35_p-1\",\n      \"han-fei-zi_ch-35_p-2\",\n      \"han-fei-zi_ch-35_p-3\",\n      \"han-fei-zi_ch-35_p-4\",\n      \"han-fei-zi_ch-35_p-5\",\n      \"han-fei-zi_ch-35_p-6\",\n      \"han-fei-zi_ch-35_p-7\",\n      \"han-fei-zi_ch-35_p-8\",\n      \"han-fei-zi_ch-35_p-9\",\n      \"han-fei-zi_ch-35_p-10\",\n      \"han-fei-zi_ch-35_p-11\",\n      \"han-fei-zi_ch-35_p-12\",\n      \"han-fei-zi_ch-35_p-13\",\n      \"han-fei-zi_ch-35_p-14\",\n      \"han-fei-zi_ch-35_p-15\",\n      \"han-fei-zi_ch-35_p-16\",\n      \"han-fei-zi_ch-35_p-17\",\n      \"han-fei-zi_ch-35_p-18\",\n      \"han-fei-zi_ch-35_p-19\",\n      \"han-fei-zi_ch-35_p-20\",\n      \"han-fei-zi_ch-35_p-21\",\n      \"han-fei-zi_ch-35_p-22\",\n      \"han-fei-zi_ch-35_p-23\",\n      \"han-fei-zi_ch-35_p-24\",\n      \"han-fei-zi_ch-35_p-25\",\n      \"han-fei-zi_ch-35_p-26\",\n      \"han-fei-zi_ch-35_p-27\",\n      \"han-fei-zi_ch-35_p-28\",\n      \"han-fei-zi_ch-35_p-29\",\n      \"han-fei-zi_ch-35_p-30\",\n      \"han-fei-zi_ch-35_p-31\",\n      \"han-fei-zi_ch-35_p-32\",\n      \"han-fei-zi_ch-35_p-33\",\n      \"han-fei-zi_ch-35_p-34\",\n      \"han-fei-zi_ch-35_p-35\",\n      \"han-fei-zi_ch-35_p-36\",\n      \"han-fei-zi_ch-35_p-37\",\n      \"han-fei-zi_ch-35_p-38\",\n      \"han-fei-zi_ch-35_p-39\",\n      \"han-fei-zi_ch-35_p-40\",\n      \"han-fei-zi_ch-35_p-41\",\n      \"han-fei-zi_ch-35_p-42\",\n      \"han-fei-zi_ch-35_p-43\",\n      \"han-fei-zi_ch-35_p-44\",\n      \"han-fei-zi_ch-35_p-45\",\n      \"han-fei-zi_ch-35_p-46\",\n      \"han-fei-zi_ch-35_p-47\",\n      \"han-fei-zi_ch-35_p-48\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-35_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 1,\n      \"canonicalText\": \"一、賞罰共則禁令不行，何以明之，明之以造父、於期。子罕為出彘，田恆為圃池，故宋君、簡公弒。患在王良、造父之共車，田連、成竅之共琴也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-1_s-1\",\n        \"han-fei-zi_ch-35_p-1_s-2\",\n        \"han-fei-zi_ch-35_p-1_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一、賞賜與刑罰共則禁令不行，何以明的，明的以造父、於期。子罕為出彘，田恆為圃池，所以宋國君、簡公弒。患在王良、造父的共車，田連、成竅的共琴啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「一、賞罰共則禁令不行，何以明之，明之以造父、於期」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「賞」、「罰」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一賞罰共則禁令不行何以明之明之以造父於期子罕為出」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「子罕為出彘，田恆為圃池，故宋君、簡公弒」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 2,\n      \"canonicalText\": \"二、治強生於法，弱亂生於阿，君明於此，則正賞罰而非仁下也。爵祿生於功，誅罰生於罪，臣明於此，則盡死力而非忠君也。君通於不仁，臣通於不忠，則可以王矣。昭襄知主情，而不發五苑；田鮪知臣情，故教田章；而公儀辭魚。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-2_s-1\",\n        \"han-fei-zi_ch-35_p-2_s-2\",\n        \"han-fei-zi_ch-35_p-2_s-3\",\n        \"han-fei-zi_ch-35_p-2_s-4\",\n        \"han-fei-zi_ch-35_p-2_s-5\",\n        \"han-fei-zi_ch-35_p-2_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"二、治強生於法規法令，弱亂生於阿，國君明於此，則正賞賜與刑罰而且絕不是仁下啊。爵祿生於功，誅刑罰生於罪，臣屬明於此，則盡死力而且絕不是忠國君啊。國君通於不仁，臣屬通於不忠，則可以王矣。昭襄知主情，而且不發五苑；田鮪知臣屬情，所以教田章；而且公儀辭魚。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「二、治強生於法，弱亂生於阿，君明於此，則正賞罰而非仁下也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「二」、「治」、「強」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「二治強生於法弱亂生於阿君明於此則正賞罰而非仁下也」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「爵祿生於功，誅罰生於罪，臣明於此，則盡死力而非忠君也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 3,\n      \"canonicalText\": \"三、明主者、鑒於外也，而外事不得不成，故蘇代非齊王。人主鑒於士也，而居者不適不顯，故潘壽言禹情。人主無所覺悟，方吾知之，故恐同衣於族，而況借於權乎？吳章知之，故說以佯，而況借於誠乎？趙王惡虎目而壅；明主之道，如周行人之卻衛侯也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-3_s-1\",\n        \"han-fei-zi_ch-35_p-3_s-2\",\n        \"han-fei-zi_ch-35_p-3_s-3\",\n        \"han-fei-zi_ch-35_p-3_s-4\",\n        \"han-fei-zi_ch-35_p-3_s-5\",\n        \"han-fei-zi_ch-35_p-3_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"三、明主的人或事、鑒於外啊，而且外事不得不成，所以蘇代絕不是齊王。人主鑒於士啊，而且居的人或事不適不顯，所以潘壽言禹情。人主無所覺悟，方吾知的，所以恐同衣於族，而且況借於權乎？吳章知的，所以說以佯，而且況借於誠乎？趙王惡虎目而且壅；明主的道，如周行人的卻衛侯啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「三、明主者、鑒於外也，而外事不得不成，故蘇代非齊王」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「三」、「明」、「主」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「三明主者鑒於外也而外事不得不成故蘇代非齊王人主鑒」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「人主鑒於士也，而居者不適不顯，故潘壽言禹情」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 4,\n      \"canonicalText\": \"四、人主者，守法責成以立功者也。聞有吏雖亂而有獨善之民，不聞有亂民而有獨治之吏，故明主治吏不治民。說在搖木之本，與引網之綱。故失火之嗇夫，不可不論也。救火者，吏操壺走火、則一人之用也，操鞭使人、則役萬夫。故所遇術者，如造父之遇驚馬，牽馬推車則不能進，代御執轡持筴則馬鹹騖矣。是以說在椎鍛平夷，榜檠矯直。不然，敗在淖齒用齊戮閔王，李兌用趙餓主父也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-4_s-1\",\n        \"han-fei-zi_ch-35_p-4_s-2\",\n        \"han-fei-zi_ch-35_p-4_s-3\",\n        \"han-fei-zi_ch-35_p-4_s-4\",\n        \"han-fei-zi_ch-35_p-4_s-5\",\n        \"han-fei-zi_ch-35_p-4_s-6\",\n        \"han-fei-zi_ch-35_p-4_s-7\",\n        \"han-fei-zi_ch-35_p-4_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"四、人主的人或事，守法規法令責成以立功的人或事啊。聞有吏雖亂而且有獨善的民，不聞有亂民而且有獨治的吏，所以明主治吏不治民。說在搖木的本，與引網的綱。所以失火的嗇夫，不可不論啊。救火的人或事，吏操壺走火、則一人的用啊，操鞭使人、則役萬夫。所以所遇督察權術的人或事，如造父的遇驚馬，牽馬推車則不能進，代御執轡持筴則馬鹹騖矣。是以說在椎鍛平夷，榜檠矯直。不然，敗在淖齒用齊戮閔王，李兌用趙餓主父啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「四、人主者，守法責成以立功者也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「四」、「人」、「主」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「四人主者守法責成以立功者也聞有吏雖亂而有獨善之民」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「聞有吏雖亂而有獨善之民，不聞有亂民而有獨治之吏，故明主治吏不治民」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 5,\n      \"canonicalText\": \"五、因事之理則不勞而成，故茲鄭之踞轅而歌以上高梁也。其患在趙簡主稅吏請輕重，薄疑之言國中飽；簡主喜而府庫虛，百姓餓而姦吏富也。故桓公巡民而管仲省腐財怨女。不然，則在延陵乘馬不得進，造父過之而為之泣也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-5_s-1\",\n        \"han-fei-zi_ch-35_p-5_s-2\",\n        \"han-fei-zi_ch-35_p-5_s-3\",\n        \"han-fei-zi_ch-35_p-5_s-4\",\n        \"han-fei-zi_ch-35_p-5_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"五、因事的理則不勞而且成，所以茲鄭的踞轅而且歌以上高梁啊。他的患在趙簡主稅吏請輕重，薄疑的言國中飽；簡主喜而且府庫虛，百姓餓而且姦吏富啊。所以桓公巡民而且管仲省腐財怨女。不然，則在延陵乘馬不得進，造父過的而且為的泣啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「五、因事之理則不勞而成，故茲鄭之踞轅而歌以上高梁也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「五」、「事」、「理」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「五因事之理則不勞而成故茲鄭之踞轅而歌以上高梁也其」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「其患在趙簡主稅吏請輕重，薄疑之言國中飽」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 6,\n      \"canonicalText\": \"右經\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-6_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"右經。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「右經」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「右」、「經」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「右經」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 7,\n      \"canonicalText\": \"說一\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-7_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說一。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「說一」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「一」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說一」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 8,\n      \"canonicalText\": \"造父御四馬，馳驟周旋而恣欲於馬。恣欲於馬者，擅轡筴之制也。然馬驚於出彘，而造父不能禁制者，非轡筴之嚴不足也，威分於出彘也。王子於期為駙駕，轡筴不用而擇欲於馬，擅芻水之利也。然馬過於圃池而駙馬敗者，非芻水之利不足也，德分於圃池也。故王良、造父，天下之善御者也，然而使王良操左革而叱吒之，使造父操右革而鞭笞之，馬不能行十里，共故也。田連、成竅，天下善鼓琴者也，然而田連鼓上，成竅擫下，而不能成曲，亦共故也。夫以王良、造父之巧，共轡而御不能使馬，人主安能與其臣共權以為治？以田連、成竅之巧，共琴而不能成曲，人主又安能與其臣共勢以成功乎？\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-8_s-1\",\n        \"han-fei-zi_ch-35_p-8_s-2\",\n        \"han-fei-zi_ch-35_p-8_s-3\",\n        \"han-fei-zi_ch-35_p-8_s-4\",\n        \"han-fei-zi_ch-35_p-8_s-5\",\n        \"han-fei-zi_ch-35_p-8_s-6\",\n        \"han-fei-zi_ch-35_p-8_s-7\",\n        \"han-fei-zi_ch-35_p-8_s-8\",\n        \"han-fei-zi_ch-35_p-8_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"造父御四馬，馳驟周旋而且恣欲於馬。恣欲於馬的人或事，擅轡筴的制啊。然馬驚於出彘，而且造父不能禁制的人或事，絕不是轡筴的嚴不足啊，威分於出彘啊。王子於期為駙駕，轡筴不用而且擇欲於馬，擅芻水的利啊。然馬過於圃池而且駙馬敗的人或事，絕不是芻水的利不足啊，德分於圃池啊。所以王良、造父，天下的善御的人或事啊，然而且使王良操左革而且叱吒的，使造父操右革而且鞭笞的，馬不能行十里，共所以啊。田連、成竅，天下善鼓琴的人或事啊，然而且田連鼓上，成竅擫下，而且不能成曲，亦共所以啊。夫以王良、造父的巧，共轡而且御不能使馬，人主安能與他的臣屬共權以為治？以田連、成竅的巧，共琴而且不能成曲，人主又安能與他的臣屬共權位威勢以成功乎？\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「造父御四馬，馳驟周旋而恣欲於馬」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「造」、「父」、「御」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「造父御四馬馳驟周旋而恣欲於馬恣欲於馬者擅轡筴之制」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「恣欲於馬者，擅轡筴之制也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 9,\n      \"canonicalText\": \"一曰。造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池，去車走池，駕敗。王子於期為趙簡主取道爭千里之表，其始發也，彘伏溝中，王子於期齊轡筴而進之，彘突出於溝中，馬驚駕敗。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-9_s-1\",\n        \"han-fei-zi_ch-35_p-9_s-2\",\n        \"han-fei-zi_ch-35_p-9_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池，去車走池，駕敗。王子於期為趙簡主取道爭千里的表，他的始發啊，彘伏溝中，王子於期齊轡筴而且進的，彘突出於溝中，馬驚駕敗。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池，去車走池，駕敗」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「造」、「父」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰造父為齊王駙駕渴馬服成效駕圃中渴馬見圃池去車」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「王子於期為趙簡主取道爭千里之表，其始發也，彘伏溝中，王子於期齊轡筴而進之，彘突出於溝中，馬驚駕敗」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 10,\n      \"canonicalText\": \"司城子罕謂宋君曰：「慶賞賜與，民之所喜也，君自行之。殺戮誅罰，民之所惡也，臣請當之。」宋君曰：「諾。」於是出威令，誅大臣，君曰「問子罕」也。於是大臣畏之，細民歸之。處期年，子罕殺宋君而奪政。故子罕為出彘以奪其君國。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-10_s-1\",\n        \"han-fei-zi_ch-35_p-10_s-2\",\n        \"han-fei-zi_ch-35_p-10_s-3\",\n        \"han-fei-zi_ch-35_p-10_s-4\",\n        \"han-fei-zi_ch-35_p-10_s-5\",\n        \"han-fei-zi_ch-35_p-10_s-6\",\n        \"han-fei-zi_ch-35_p-10_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"司城子罕謂宋國君說道：慶賞賜賜與，民的所喜啊，國君自行的。殺戮誅刑罰，民的所惡啊，臣屬請當的。宋國君說道：諾。於是出威令，誅大臣屬，國君說道：問子罕啊。於是大臣屬畏的，細民歸的。處期年，子罕殺宋國君而且奪政。所以子罕為出彘以奪他的國君國。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「司城子罕謂宋君曰：「慶賞賜與，民之所喜也，君自行之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「司」、「城」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「司城子罕謂宋君曰慶賞賜與民之所喜也君自行之殺戮誅」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「殺戮誅罰，民之所惡也，臣請當之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 11,\n      \"canonicalText\": \"簡公在上位，罰重而誅嚴，厚賦斂而殺戮民。田成恆設慈愛，明寬厚。簡公以齊民為渴馬，不以恩加民，而田成恆以仁厚為圃池也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-11_s-1\",\n        \"han-fei-zi_ch-35_p-11_s-2\",\n        \"han-fei-zi_ch-35_p-11_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"簡公在上位，刑罰制裁重而且誅嚴，厚賦斂而且殺戮民。田成恆設慈愛，明寬厚。簡公以齊民為渴馬，不以恩加民，而且田成恆以仁厚為圃池啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「簡公在上位，罰重而誅嚴，厚賦斂而殺戮民」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「簡」、「公」、「在」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「簡公在上位罰重而誅嚴厚賦斂而殺戮民田成恆設慈愛明」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「田成恆設慈愛，明寬厚」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 12,\n      \"canonicalText\": \"一曰。造父為齊王駙駕，以渴服馬，百日而服成，服成請效駕，齊王王曰：「效駕於圃中。」造父驅車入圃，馬見圃池而走，造父不能禁。造父以渴服馬久矣，今馬見池，駻而走，雖造父不能治。今簡公之以法禁其眾久矣，而田成恆利之，是田成恆傾圃池而示渴民也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-12_s-1\",\n        \"han-fei-zi_ch-35_p-12_s-2\",\n        \"han-fei-zi_ch-35_p-12_s-3\",\n        \"han-fei-zi_ch-35_p-12_s-4\",\n        \"han-fei-zi_ch-35_p-12_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。造父為齊王駙駕，以渴服馬，百日而且服成，服成請效駕，齊王王說道：效駕於圃中。造父驅車入圃，馬見圃池而且走，造父不能禁。造父以渴服馬久矣，今馬見池，駻而且走，雖造父不能治。今簡公的以國家法度法規禁他的眾久矣，而且田成恆利的，是田成恆傾圃池而且示渴民啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「造父為齊王駙駕，以渴服馬，百日而服成，服成請效駕，齊王王曰：「效駕於圃中」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「造」、「父」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰造父為齊王駙駕以渴服馬百日而服成服成請效駕齊」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」造父驅車入圃，馬見圃池而走，造父不能禁」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 13,\n      \"canonicalText\": \"一曰。王子於期為宋君為千里之逐。已駕，察手吻文。且發矣，驅而前之，輪中繩引而卻之，馬掩跡。拊而發之，彘逸出於竇中，馬退而卻，筴不能進前也，馬駻而走，轡不能正也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-13_s-1\",\n        \"han-fei-zi_ch-35_p-13_s-2\",\n        \"han-fei-zi_ch-35_p-13_s-3\",\n        \"han-fei-zi_ch-35_p-13_s-4\",\n        \"han-fei-zi_ch-35_p-13_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。王子於期為宋君主統治者為千里的逐。已駕，察手吻文。且發矣，驅而且前的，輪中繩引而且卻的，馬掩跡。拊而且發的，彘逸出於竇中，馬退而且卻，筴不能進前啊，馬駻而且走，轡不能正啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「王子於期為宋君為千里之逐」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「王」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰王子於期為宋君為千里之逐已駕察手吻文且發矣驅」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「已駕，察手吻文」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 14,\n      \"canonicalText\": \"一曰。司城子罕謂宋君曰：「慶賞賜予者，民之所好也，君自行之。誅罰殺戮者，民之所惡也，臣請當之。」於是戮細民而誅大臣，君曰「與子罕議之」。居期年，民知殺生之命制於子罕也，故一國歸焉。故子罕劫宋君而奪其政，法不能禁也。故曰子罕為出彘，而田成常為圃池也。令王良、造父共車，人操一邊轡而入門閭，駕必敗而道不至也。令田連、成竅共琴，人撫一絃而揮，則音必敗曲不遂矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-14_s-1\",\n        \"han-fei-zi_ch-35_p-14_s-2\",\n        \"han-fei-zi_ch-35_p-14_s-3\",\n        \"han-fei-zi_ch-35_p-14_s-4\",\n        \"han-fei-zi_ch-35_p-14_s-5\",\n        \"han-fei-zi_ch-35_p-14_s-6\",\n        \"han-fei-zi_ch-35_p-14_s-7\",\n        \"han-fei-zi_ch-35_p-14_s-8\",\n        \"han-fei-zi_ch-35_p-14_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。司城子罕謂宋國君說道：慶賞賜賜予的人或事，民的所好啊，國君自行的。誅刑罰殺戮的人或事，民的所惡啊，臣屬請當的。於是戮細民而且誅大臣屬，國君說道：與子罕議的。居期年，民知殺生的命制於子罕啊，所以一國歸焉。所以子罕劫宋國君而且奪他的政，法規法令不能禁啊。因此韓絕不是子評論說道：子罕為出彘，而且田成常為圃池啊。令王良、造父共車，人操一邊轡而且入門閭，駕必敗而且道不至啊。令田連、成竅共琴，人撫一絃而且揮，則音必敗曲不遂矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「司城子罕謂宋君曰：「慶賞賜予者，民之所好也，君自行之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「司」、「城」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰司城子罕謂宋君曰慶賞賜予者民之所好也君自行之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「誅罰殺戮者，民之所惡也，臣請當之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-15\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 15,\n      \"canonicalText\": \"說二\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-15_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說二。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「說二」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「二」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說二」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 16,\n      \"canonicalText\": \"秦昭王有病，百姓裏買牛而家為王禱。公孫述出見之，入賀王曰：「百姓乃皆裏買牛為王禱。」王使人問之，果有之。王曰：「訾之人二甲。夫非令而擅禱，是愛寡人也。夫愛寡人，寡人亦且改法而心與之相循者，是法不立，法不立，亂亡之道也。不如人罰二甲而復與為治。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-16_s-1\",\n        \"han-fei-zi_ch-35_p-16_s-2\",\n        \"han-fei-zi_ch-35_p-16_s-3\",\n        \"han-fei-zi_ch-35_p-16_s-4\",\n        \"han-fei-zi_ch-35_p-16_s-5\",\n        \"han-fei-zi_ch-35_p-16_s-6\",\n        \"han-fei-zi_ch-35_p-16_s-7\",\n        \"han-fei-zi_ch-35_p-16_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦昭王有病，百姓裏買牛而且家為王禱。公孫述出見的，入賀王說道：百姓乃皆裏買牛為王禱。王使人問的，果有的。王說道：訾的人二甲。夫絕不是令而且擅禱，是愛寡人啊。夫愛寡人，寡人亦且改法規法令而且心與的相循的人或事，是法規法令不立，法規法令不立，亂亡的道啊。不如人刑罰二甲而且復與為治。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「秦昭王有病，百姓裏買牛而家為王禱」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「秦」、「昭」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「秦昭王有病百姓裏買牛而家為王禱公孫述出見之入賀王」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「公孫述出見之，入賀王曰：「百姓乃皆裏買牛為王禱」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 17,\n      \"canonicalText\": \"一曰。秦襄王病，百姓為之禱，病癒，殺牛塞禱。郎中閻遏、公孫衍出見之曰：「非社臘之時也，奚自殺牛而祠社？」怪而問之。百姓曰：「人主病，為之禱，今病癒，殺牛塞禱。」閻遏、公孫衍說，見王，拜賀曰：「過堯、舜矣。」王驚曰：「何謂也？」對曰：「堯、舜，其民未至為之禱也，今王病，而民以牛禱，病癒，殺牛塞禱，故臣竊以王為過堯、舜也。」王因使人問之何裏為之，訾其里正與伍老屯二甲。閻遏、公孫衍媿不敢言。居數月，王飲酒酣樂，閻遏、公孫衍謂王曰：「前時臣竊以王為過堯、舜，非直敢諛也。堯、舜病，且其民未至為之禱也。今王病而民以牛禱，病癒，殺牛塞禱。今乃訾其里正與伍老屯二甲，臣竊怪之。」王曰：「子何故不知於此。彼民之所以為我用者，非以吾愛之為我用者也，以吾勢之為我用者也。吾釋勢與民相收，若是，吾適不愛，而民因不為我用也，故遂絕愛道也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-17_s-1\",\n        \"han-fei-zi_ch-35_p-17_s-2\",\n        \"han-fei-zi_ch-35_p-17_s-3\",\n        \"han-fei-zi_ch-35_p-17_s-4\",\n        \"han-fei-zi_ch-35_p-17_s-5\",\n        \"han-fei-zi_ch-35_p-17_s-6\",\n        \"han-fei-zi_ch-35_p-17_s-7\",\n        \"han-fei-zi_ch-35_p-17_s-8\",\n        \"han-fei-zi_ch-35_p-17_s-9\",\n        \"han-fei-zi_ch-35_p-17_s-10\",\n        \"han-fei-zi_ch-35_p-17_s-11\",\n        \"han-fei-zi_ch-35_p-17_s-12\",\n        \"han-fei-zi_ch-35_p-17_s-13\",\n        \"han-fei-zi_ch-35_p-17_s-14\",\n        \"han-fei-zi_ch-35_p-17_s-15\",\n        \"han-fei-zi_ch-35_p-17_s-16\",\n        \"han-fei-zi_ch-35_p-17_s-17\",\n        \"han-fei-zi_ch-35_p-17_s-18\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。秦襄王病，百姓為的禱，病癒，殺牛塞禱。郎中閻遏、公孫衍出見的說道：絕不是社臘的時啊，奚自殺牛而且祠社？怪而且問的。百姓說道：人主病，為的禱，今病癒，殺牛塞禱。閻遏、公孫衍說，見王，拜賀說道：過堯、舜矣。王驚說道：何謂啊？對說道：堯、舜，他的民未至為的禱啊，今王病，而且民以牛禱，病癒，殺牛塞禱，所以臣屬竊以王為過堯、舜啊。王因使人問的何裏為的，訾他的里正與伍老屯二甲。閻遏、公孫衍媿不敢言。居數月，王飲酒酣樂，閻遏、公孫衍謂王說道：前時臣屬竊以王為過堯、舜，絕不是直敢諛啊。堯、舜病，且他的民未至為的禱啊。今王病而且民以牛禱，病癒，殺牛塞禱。今乃訾他的里正與伍老屯二甲，臣屬竊怪的。王說道：子何所以不知於此。彼民的所以為我用的人或事，絕不是以吾愛的為我用的人或事啊，以吾權位威勢的為我用的人或事啊。吾釋權位威勢與民相收，若是，吾適不愛，而且民因不為我用啊，所以遂絕愛道啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「秦襄王病，百姓為之禱，病癒，殺牛塞禱」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「秦」、「襄」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰秦襄王病百姓為之禱病癒殺牛塞禱郎中閻遏公孫衍」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「郎中閻遏、公孫衍出見之曰：「非社臘之時也，奚自殺牛而祠社」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 18,\n      \"canonicalText\": \"秦大饑，應侯請曰：「五苑之草著、蔬菜、橡果、棗栗，足以活民，請發之。」昭襄王曰：「吾秦法，使民有功而受賞，有罪而受誅。今發五苑之蔬草者，使民有功與無功俱賞也。夫使民有功與無功俱賞者，此亂之道也。夫發五苑而亂，不如棄棗蔬而治。」一曰。「今發五苑之蓏蔬棗栗足以活民，是用民有功與無功爭取也。夫生而亂，不如死而治，大夫其釋之。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-18_s-1\",\n        \"han-fei-zi_ch-35_p-18_s-2\",\n        \"han-fei-zi_ch-35_p-18_s-3\",\n        \"han-fei-zi_ch-35_p-18_s-4\",\n        \"han-fei-zi_ch-35_p-18_s-5\",\n        \"han-fei-zi_ch-35_p-18_s-6\",\n        \"han-fei-zi_ch-35_p-18_s-7\",\n        \"han-fei-zi_ch-35_p-18_s-8\",\n        \"han-fei-zi_ch-35_p-18_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦大饑，應侯請說道：五苑的草著、蔬菜、橡果、棗栗，足以活民，請發的。昭襄王說道：吾秦法規法令，使民有功而且受賞賜，有罪而且受誅。今發五苑的蔬草的人或事，使民有功與無功俱賞賜啊。夫使民有功與無功俱賞賜的人或事，此亂的道啊。夫發五苑而且亂，不如棄棗蔬而且治。一說道：。今發五苑的蓏蔬棗栗足以活民，是用民有功與無功爭取啊。夫生而且亂，不如死而且治，大夫他的釋的。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「秦大饑，應侯請曰：「五苑之草著、蔬菜、橡果、棗栗，足以活民，請發之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「秦」、「大」、「饑」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「秦大饑應侯請曰五苑之草著蔬菜橡果棗栗足以活民請發」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」昭襄王曰：「吾秦法，使民有功而受賞，有罪而受誅」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-19\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 19,\n      \"canonicalText\": \"田鮪教其子田章曰：「欲利而身，先利而君；欲富而家，先富而國。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-19_s-1\",\n        \"han-fei-zi_ch-35_p-19_s-2\",\n        \"han-fei-zi_ch-35_p-19_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"田鮪教他的子田章說道：欲利而且身，先利而且君主統治者；欲富而且家，先富而且國。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「田鮪教其子田章曰：「欲利而身，先利而君」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「田」、「鮪」、「教」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「田鮪教其子田章曰欲利而身先利而君欲富而家先富而國」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「欲富而家，先富而國」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-20\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 20,\n      \"canonicalText\": \"一曰。田鮪教其子田章曰：「主賣官爵，臣賣智力，故自恃無恃人。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-20_s-1\",\n        \"han-fei-zi_ch-35_p-20_s-2\",\n        \"han-fei-zi_ch-35_p-20_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。田鮪教他的子田章說道：主賣官爵，臣屬賣智力，所以自恃無恃人。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「田鮪教其子田章曰：「主賣官爵，臣賣智力，故自恃無恃人」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「田」、「鮪」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰田鮪教其子田章曰主賣官爵臣賣智力故自恃無恃人」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「田鮪教其子田章曰：「主賣官爵，臣賣智力，故自恃無恃人」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-21\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 21,\n      \"canonicalText\": \"公儀休相魯而嗜魚，一國盡爭買魚而獻之，公儀子不受，其弟諫曰：「夫子嗜魚而不受者何也？」對曰：「夫唯嗜魚，故不受也。夫即受魚，必有下人之色，有下人之色，將枉於法，枉於法則免於相，雖嗜魚，此不必能自給致我魚，我又不能自給魚。即無受魚而不免於相，雖嗜魚，我能長自給魚。」此明夫恃人不如自恃也，明於人之為己者不如己之自為也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-21_s-1\",\n        \"han-fei-zi_ch-35_p-21_s-2\",\n        \"han-fei-zi_ch-35_p-21_s-3\",\n        \"han-fei-zi_ch-35_p-21_s-4\",\n        \"han-fei-zi_ch-35_p-21_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"公儀休相魯而且嗜魚，一國盡爭買魚而且獻的，公儀子不受，他的弟諫說道：夫子嗜魚而且不受的人或事何啊？對說道：夫唯嗜魚，所以不受啊。夫即受魚，必有下人的色，有下人的色，將枉於法規法令，枉於法規法令則免於相，雖嗜魚，此不必能自給致我魚，我又不能自給魚。即無受魚而且不免於相，雖嗜魚，我能長自給魚。此明夫恃人不如自恃啊，明於人的為己的人或事不如己的自為啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「公儀休相魯而嗜魚，一國盡爭買魚而獻之，公儀子不受，其弟諫曰：「夫子嗜魚而不受者何也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「公」、「儀」、「休」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「公儀休相魯而嗜魚一國盡爭買魚而獻之公儀子不受其弟」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」對曰：「夫唯嗜魚，故不受也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-22\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 22,\n      \"canonicalText\": \"說三\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-22_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說三。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「說三」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「三」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說三」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 23,\n      \"canonicalText\": \"子之相燕，貴而主斷。蘇代為齊使燕，王問之曰：「齊王亦何如主也？」對曰：「必不霸矣。」燕王曰：「何也？」對曰：「昔桓公之霸也，內事屬鮑叔，外事屬管仲，桓公被髮而御婦人，日遊於市。今齊王不信其大臣。」於是燕王因益大信子之。子之聞之，使人遺蘇代金百鎰，而聽其所使之。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-23_s-1\",\n        \"han-fei-zi_ch-35_p-23_s-2\",\n        \"han-fei-zi_ch-35_p-23_s-3\",\n        \"han-fei-zi_ch-35_p-23_s-4\",\n        \"han-fei-zi_ch-35_p-23_s-5\",\n        \"han-fei-zi_ch-35_p-23_s-6\",\n        \"han-fei-zi_ch-35_p-23_s-7\",\n        \"han-fei-zi_ch-35_p-23_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"子的相燕，貴而且主斷。蘇代為齊使燕，王問的說道：齊王亦何如主啊？對說道：必不霸矣。燕王說道：何啊？對說道：昔桓公的霸啊，內事屬鮑叔，外事屬管仲，桓公被髮而且御婦人，日遊於市。今齊王不信他的大臣屬。於是燕王因益大信子的。子的聞的，使人遺蘇代金百鎰，而且聽他的所使的。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「子之相燕，貴而主斷」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「子」、「相」、「燕」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「子之相燕貴而主斷蘇代為齊使燕王問之曰齊王亦何如主」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「蘇代為齊使燕，王問之曰：「齊王亦何如主也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 24,\n      \"canonicalText\": \"一曰。蘇代為秦使燕，見無益子之，則必不得事而還，貢賜又不出，於是見燕王乃譽齊王。燕王曰：「齊王何若是之賢也！則將必王乎？」蘇代曰：「救亡不暇，安得王哉？」燕王曰：「何也？」曰：「其任所愛不均。」燕王曰：「其亡何也？」曰：「昔者齊桓公愛管仲，置以為仲父，內事理焉，外事斷焉，舉國而歸之，故一匡天下，九合諸侯。今齊任所愛不均，是以知其亡也。」燕王曰：「今吾任子之，天下未之聞也。」於是明日張朝而聽子之。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-24_s-1\",\n        \"han-fei-zi_ch-35_p-24_s-2\",\n        \"han-fei-zi_ch-35_p-24_s-3\",\n        \"han-fei-zi_ch-35_p-24_s-4\",\n        \"han-fei-zi_ch-35_p-24_s-5\",\n        \"han-fei-zi_ch-35_p-24_s-6\",\n        \"han-fei-zi_ch-35_p-24_s-7\",\n        \"han-fei-zi_ch-35_p-24_s-8\",\n        \"han-fei-zi_ch-35_p-24_s-9\",\n        \"han-fei-zi_ch-35_p-24_s-10\",\n        \"han-fei-zi_ch-35_p-24_s-11\",\n        \"han-fei-zi_ch-35_p-24_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。蘇代為秦使燕，見無益子的，則必不得事而且還，貢賜又不出，於是見燕王乃譽齊王。燕王說道：齊王何若是的賢啊！則將必王乎？蘇代說道：救亡不暇，安得王哉？燕王說道：何啊？說道：他的任所愛不均。燕王說道：他的亡何啊？說道：昔的人或事齊桓公愛管仲，置以為仲父，內事理焉，外事斷焉，舉國而且歸的，所以一匡天下，九合諸侯。今齊任所愛不均，是以知他的亡啊。燕王說道：今吾任子的，天下未的聞啊。於是明日張朝而且聽子的。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「蘇代為秦使燕，見無益子之，則必不得事而還，貢賜又不出，於是見燕王乃譽齊王」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「蘇」、「代」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰蘇代為秦使燕見無益子之則必不得事而還貢賜又不」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「燕王曰：「齊王何若是之賢也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-25\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 25,\n      \"canonicalText\": \"潘壽謂燕王曰：「王不如以國讓子之。人所以謂堯賢者，以其讓天下於許由，許由必不受也，則是堯有讓許由之名而實不失天下也。今王以國讓子之，子之必不受也，則是王有讓子之之名而與堯同行也。」於是燕王因舉國而屬之，子之大重。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-25_s-1\",\n        \"han-fei-zi_ch-35_p-25_s-2\",\n        \"han-fei-zi_ch-35_p-25_s-3\",\n        \"han-fei-zi_ch-35_p-25_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"潘壽謂燕王說道：王不如以國讓子的。人所以謂堯賢的人或事，以他的讓天下於許由，許由必不受啊，則是堯有讓許由的名而且實不失天下啊。今王以國讓子的，子的必不受啊，則是王有讓子的的名而且與堯同行啊。於是燕王因舉國而且屬的，子的大重。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「潘壽謂燕王曰：「王不如以國讓子之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「潘」、「壽」、「謂」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「潘壽謂燕王曰王不如以國讓子之人所以謂堯賢者以其讓」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「人所以謂堯賢者，以其讓天下於許由，許由必不受也，則是堯有讓許由之名而實不失天下也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 26,\n      \"canonicalText\": \"一曰。潘壽，闞者。燕使人聘之。潘壽見燕王曰：「臣恐子之之如益也。」王曰：「何益哉？」對曰：「古者禹死，將傳天下於益，啟之人因相與攻益而立啟。今王信愛子之，將傳國子之，太子之人盡懷印為，子之之人無一人在朝廷者，王不幸棄群臣，則子之亦益也。」王因收吏璽自三百石以上皆效之子之，子之大重。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-26_s-1\",\n        \"han-fei-zi_ch-35_p-26_s-2\",\n        \"han-fei-zi_ch-35_p-26_s-3\",\n        \"han-fei-zi_ch-35_p-26_s-4\",\n        \"han-fei-zi_ch-35_p-26_s-5\",\n        \"han-fei-zi_ch-35_p-26_s-6\",\n        \"han-fei-zi_ch-35_p-26_s-7\",\n        \"han-fei-zi_ch-35_p-26_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。潘壽，闞的人或事。燕使人聘的。潘壽見燕王說道：臣屬恐子的的如益啊。王說道：何益哉？對說道：古的人或事禹死，將傳天下於益，啟的人因相與攻益而且立啟。今王信愛子的，將傳國子的，太子的人盡懷印為，子的的人無一人在朝廷的人或事，王不幸棄群臣屬，則子的亦益啊。王因收吏璽自三百石以上皆效的子的，子的大重。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「潘壽，闞者」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「潘」、「壽」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰潘壽闞者燕使人聘之潘壽見燕王曰臣恐子之之如益」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「燕使人聘之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-27\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 27,\n      \"canonicalText\": \"夫人主之所以鏡照者，諸侯之士徒也，今諸侯之士徒皆私門之黨也。人主之所以自淺娟者，巖穴之士徒也，今巖穴之士徒皆私門之舍人也。是何也？奪褫之資在子之也。故吳章曰：「人主不佯憎愛人，佯愛人不得復憎也，佯憎人不得復愛也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-27_s-1\",\n        \"han-fei-zi_ch-35_p-27_s-2\",\n        \"han-fei-zi_ch-35_p-27_s-3\",\n        \"han-fei-zi_ch-35_p-27_s-4\",\n        \"han-fei-zi_ch-35_p-27_s-5\",\n        \"han-fei-zi_ch-35_p-27_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫人主的所以鏡照的人或事，諸侯的士徒啊，今諸侯的士徒皆私門的黨啊。人主的所以自淺娟的人或事，巖穴的士徒啊，今巖穴的士徒皆私門的舍人啊。是何啊？奪褫的資在子的啊。所以吳章說道：人主不佯憎愛人，佯愛人不得復憎啊，佯憎人不得復愛啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「夫人主之所以鏡照者，諸侯之士徒也，今諸侯之士徒皆私門之黨也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「人」、「主」、「鏡」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「夫人主之所以鏡照者諸侯之士徒也今諸侯之士徒皆私門」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「人主之所以自淺娟者，巖穴之士徒也，今巖穴之士徒皆私門之舍人也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 28,\n      \"canonicalText\": \"一曰。燕王欲傳國於子之也，問之潘壽，對曰：「禹愛益，而任天下於益，已而以啟人為吏。及老，而以啟為不足任天下，故傳天下於益，而勢重盡在啟也。已而啟與友黨攻益而奪之天下，是禹名傳天下於益，而實令啟自取之也。此禹之不及堯、舜明矣。今王欲傳之子之，而吏無非太子之人者也。是名傳之，而實令太子自取之也。」燕王乃收璽自三百石以上皆效之子之，子之遂重。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-28_s-1\",\n        \"han-fei-zi_ch-35_p-28_s-2\",\n        \"han-fei-zi_ch-35_p-28_s-3\",\n        \"han-fei-zi_ch-35_p-28_s-4\",\n        \"han-fei-zi_ch-35_p-28_s-5\",\n        \"han-fei-zi_ch-35_p-28_s-6\",\n        \"han-fei-zi_ch-35_p-28_s-7\",\n        \"han-fei-zi_ch-35_p-28_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。燕王欲傳國於子的啊，問的潘壽，對說道：禹愛益，而且任天下於益，已而且以啟人為吏。及老，而且以啟為不足任天下，所以傳天下於益，而且權位威勢重盡在啟啊。已而且啟與友黨攻益而且奪的天下，是禹名傳天下於益，而且實令啟自取的啊。此禹的不及堯、舜明矣。今王欲傳的子的，而且吏無絕不是太子的人的人或事啊。是名傳的，而且實令太子自取的啊。燕王乃收璽自三百石以上皆效的子的，子的遂重。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「燕王欲傳國於子之也，問之潘壽，對曰：「禹愛益，而任天下於益，已而以啟人為吏」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「燕」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰燕王欲傳國於子之也問之潘壽對曰禹愛益而任天下」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「及老，而以啟為不足任天下，故傳天下於益，而勢重盡在啟也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-29\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 29,\n      \"canonicalText\": \"方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者共家，而況君人者乃借其權而外其勢乎！」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-29_s-1\",\n        \"han-fei-zi_ch-35_p-29_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"方吾子說道：吾聞的古禮，行不與同服的人或事同車，不與同族的人或事共家，而且況國君人的人或事乃借他的權而且外他的權位威勢乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者共家，而況君人者乃借其權而外其勢乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「方」、「吾」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「方吾子曰吾聞之古禮行不與同服者同車不與同族者共家」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者共家，而況君人者乃借其權而外其勢乎」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-30\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 30,\n      \"canonicalText\": \"吳章謂韓宣王曰：「人主不可佯愛人，一日不可復憎；不可以佯憎人，一日不可復愛也。故佯憎佯愛之徵見，則諛者因資而毀譽之，雖有明主不能復收，而況於以誠借人也！」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-30_s-1\",\n        \"han-fei-zi_ch-35_p-30_s-2\",\n        \"han-fei-zi_ch-35_p-30_s-3\",\n        \"han-fei-zi_ch-35_p-30_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"吳章謂韓宣王說道：人主不可佯愛人，一日不可復憎；不可以佯憎人，一日不可復愛啊。所以佯憎佯愛的徵見，則諛的人或事因資而且毀譽的，雖有明主不能復收，而且況於以誠借人啊！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「吳章謂韓宣王曰：「人主不可佯愛人，一日不可復憎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「吳」、「章」、「謂」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「吳章謂韓宣王曰人主不可佯愛人一日不可復憎不可以佯」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「不可以佯憎人，一日不可復愛也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-31\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 31,\n      \"canonicalText\": \"趙王遊於圃中，左右以菟與虎而輟，盼然環其眼，王曰：「可惡哉，虎目也！」左右曰：「平陽君之目可惡過此。見此未有害也，見平陽君之目如此者則必死矣。」其明日，平陽君聞之，使人殺言者，而王不誅也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-31_s-1\",\n        \"han-fei-zi_ch-35_p-31_s-2\",\n        \"han-fei-zi_ch-35_p-31_s-3\",\n        \"han-fei-zi_ch-35_p-31_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"趙王遊於圃中，左右以菟與虎而且輟，盼然環他的眼，王說道：可惡哉，虎目啊！左右說道：平陽國君的目可惡過此。見此未有害啊，見平陽國君的目如此的人或事則必死矣。他的明日，平陽國君聞的，使人殺言的人或事，而且王不誅啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「趙王遊於圃中，左右以菟與虎而輟，盼然環其眼，王曰：「可惡哉，虎目也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「趙」、「王」、「遊」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「趙王遊於圃中左右以菟與虎而輟盼然環其眼王曰可惡哉」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」左右曰：「平陽君之目可惡過此」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-32\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 32,\n      \"canonicalText\": \"衛君入朝於周，周行人問其號，對曰：「諸侯闢疆。」周行人卻之曰：「諸侯不得與天子同號。」衛君乃自更曰「諸侯燬」而後內之。仲尼聞之曰：「遠哉禁偪，虛名不以借人，況實事乎！」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-32_s-1\",\n        \"han-fei-zi_ch-35_p-32_s-2\",\n        \"han-fei-zi_ch-35_p-32_s-3\",\n        \"han-fei-zi_ch-35_p-32_s-4\",\n        \"han-fei-zi_ch-35_p-32_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"衛君主統治者入朝於周，周行人問他的號，對說道：諸侯闢疆。周行人卻的說道：諸侯不得與天子同號。衛君主統治者乃自更說道：諸侯燬而且後內的。仲尼聞的說道：遠哉禁偪，虛名不以借人，況實事乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「衛君入朝於周，周行人問其號，對曰：「諸侯闢疆」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「衛」、「君」、「入」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「衛君入朝於周周行人問其號對曰諸侯闢疆周行人卻之曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」周行人卻之曰：「諸侯不得與天子同號」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-33\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 33,\n      \"canonicalText\": \"說四\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-33_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說四。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「說四」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「四」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說四」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-34\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 34,\n      \"canonicalText\": \"搖木者一一攝其葉則勞而不遍，左右拊其本而葉遍搖矣。臨淵而搖木，鳥驚而高，魚恐而下。善張網者引其綱，不一一攝萬目而後得則是勞而難，引其綱而魚已囊矣。故吏者，民之本綱者也，故聖人治吏不治民。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-34_s-1\",\n        \"han-fei-zi_ch-35_p-34_s-2\",\n        \"han-fei-zi_ch-35_p-34_s-3\",\n        \"han-fei-zi_ch-35_p-34_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"搖木的人或事一一攝他的葉則勞而且不遍，左右拊他的本而且葉遍搖矣。臨淵而且搖木，鳥驚而且高，魚恐而且下。善張網的人或事引他的綱，不一一攝萬目而且後得則是勞而且難，引他的綱而且魚已囊矣。所以吏的人或事，民的本綱的人或事啊，所以聖人治吏不治民。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「搖木者一一攝其葉則勞而不遍，左右拊其本而葉遍搖矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「搖」、「木」、「一」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「搖木者一一攝其葉則勞而不遍左右拊其本而葉遍搖矣臨」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「臨淵而搖木，鳥驚而高，魚恐而下」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-35\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 35,\n      \"canonicalText\": \"救火者，令吏挈壺甕而走火則一人之用也，操鞭箠指麾而趣使人則制萬夫。是以聖人不親細民，明主不躬小事。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-35_s-1\",\n        \"han-fei-zi_ch-35_p-35_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"救火的人或事，令吏挈壺甕而且走火則一人的用啊，操鞭箠指麾而且趣使人則制萬夫。是以聖人不親細民，明主不躬小事。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「救火者，令吏挈壺甕而走火則一人之用也，操鞭箠指麾而趣使人則制萬夫」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「救」、「火」、「令」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「救火者令吏挈壺甕而走火則一人之用也操鞭箠指麾而趣」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「是以聖人不親細民，明主不躬小事」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-36\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 36,\n      \"canonicalText\": \"造父方耨，得有子父乘車過者，馬驚而不行，其子下車牽馬，父子推車請造父助我推車，造父因收器輟而寄載之，援其子之乘，乃始檢轡持筴，未之用也而馬轡驚矣。使造父而不能御，雖盡力勞身助之推車，馬猶不肯行也。今身使佚，且寄載，有德於人者，有術而御之也。故國者君之車也，勢者君之馬也，無術以御之，身雖勞猶不免亂，有術以御之，身處佚樂之地，又致帝王之功也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-36_s-1\",\n        \"han-fei-zi_ch-35_p-36_s-2\",\n        \"han-fei-zi_ch-35_p-36_s-3\",\n        \"han-fei-zi_ch-35_p-36_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"造父方耨，得有子父乘車過的人或事，馬驚而且不行，他的子下車牽馬，父子推車請造父助我推車，造父因收器輟而且寄載的，援他的子的乘，乃始檢轡持筴，未的用啊而且馬轡驚矣。使造父而且不能御，雖盡力勞身助的推車，馬猶不肯行啊。今身使佚，且寄載，有德於人的人或事，有督察權術而且御的啊。所以國的人或事國君的車啊，權位威勢的人或事國君的馬啊，無督察權術以御的，身雖勞猶不免亂，有督察權術以御的，身處佚樂的地，又致帝王的功啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「造父方耨，得有子父乘車過者，馬驚而不行，其子下車牽馬，父子推車請造父助我推車，造父因收器輟而寄載之，援其子之乘，乃始檢轡持筴，未之用也而馬轡驚矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「造」、「父」、「方」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「造父方耨得有子父乘車過者馬驚而不行其子下車牽馬父」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「使造父而不能御，雖盡力勞身助之推車，馬猶不肯行也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-37\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 37,\n      \"canonicalText\": \"椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也，所以平不夷矯不直也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-37_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"椎鍛的人或事所以平不夷啊，榜檠的人或事所以矯不直啊，聖人的為法規法令啊，所以平不夷矯不直啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也，所以平不夷矯不直也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「椎」、「鍛」、「平」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「椎鍛者所以平不夷也榜檠者所以矯不直也聖人之為法也」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也，所以平不夷矯不直也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-38\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 38,\n      \"canonicalText\": \"淖齒之用齊也擢閔王之筋，李兌之用趙也餓殺主父。此二君者皆不能用其椎鍛榜檠，故身死為戮而為天下笑。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-38_s-1\",\n        \"han-fei-zi_ch-35_p-38_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"淖齒的用齊啊擢閔王的筋，李兌的用趙啊餓殺主父。此二國君的人或事皆不能用他的椎鍛榜檠，所以身死為戮而且為天下笑。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「淖齒之用齊也擢閔王之筋，李兌之用趙也餓殺主父」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「淖」、「齒」、「用」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「淖齒之用齊也擢閔王之筋李兌之用趙也餓殺主父此二君」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「此二君者皆不能用其椎鍛榜檠，故身死為戮而為天下笑」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-39\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 39,\n      \"canonicalText\": \"一曰。入齊則獨聞淖齒而不聞齊王，入趙則獨聞李兌而不聞趙王。故曰：人主者不操術，則威勢輕而臣擅名。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-39_s-1\",\n        \"han-fei-zi_ch-35_p-39_s-2\",\n        \"han-fei-zi_ch-35_p-39_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。入齊則獨聞淖齒而且不聞齊王，入趙則獨聞李兌而且不聞趙王。因此韓絕不是子評論說道：人主的人或事不操督察權術，則威權位威勢輕而且臣屬擅名。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「入齊則獨聞淖齒而不聞齊王，入趙則獨聞李兌而不聞趙王」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「入」、「齊」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰入齊則獨聞淖齒而不聞齊王入趙則獨聞李兌而不聞」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「故曰：人主者不操術，則威勢輕而臣擅名」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 40,\n      \"canonicalText\": \"一曰。田嬰相齊，人有說王者曰：「終歲之計，王不一以數日之間自聽之，則無以知吏之姦邪得失也。」王曰：「善。」田嬰聞之，即遽請於王而聽其計，王將聽之矣，田嬰令官具押券鬥石參升之計，王自聽計，計不勝聽，罷食，後復坐，不復暮食矣。田嬰復謂曰：「群臣所終歲日夜不敢偷怠之事也，王以一夕聽之，則群臣有為勸勉矣。」王曰：「諾。」俄而王已睡矣，吏盡揄刀削其押券升石之計。王自聽之，亂乃始生。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-40_s-1\",\n        \"han-fei-zi_ch-35_p-40_s-2\",\n        \"han-fei-zi_ch-35_p-40_s-3\",\n        \"han-fei-zi_ch-35_p-40_s-4\",\n        \"han-fei-zi_ch-35_p-40_s-5\",\n        \"han-fei-zi_ch-35_p-40_s-6\",\n        \"han-fei-zi_ch-35_p-40_s-7\",\n        \"han-fei-zi_ch-35_p-40_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。田嬰相齊，人有說王的人或事說道：終歲的計，王不一以數日的間自聽的，則無以知吏的姦邪得失啊。王說道：善。田嬰聞的，即遽請於王而且聽他的計，王將聽的矣，田嬰令官具押券鬥石參升的計，王自聽計，計不勝聽，罷食，後復坐，不復暮食矣。田嬰復謂說道：群臣屬所終歲日夜不敢偷怠的事啊，王以一夕聽的，則群臣屬有為勸勉矣。王說道：諾。俄而且王已睡矣，吏盡揄刀削他的押券升石的計。王自聽的，亂乃始生。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「田嬰相齊，人有說王者曰：「終歲之計，王不一以數日之間自聽之，則無以知吏之姦邪得失也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「田」、「嬰」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰田嬰相齊人有說王者曰終歲之計王不一以數日之間」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」王曰：「善」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-41\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 41,\n      \"canonicalText\": \"一曰。武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生之柄，故劫於李兌。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-41_s-1\",\n        \"han-fei-zi_ch-35_p-41_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生的柄，所以劫於李兌。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生之柄，故劫於李兌」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「武」、「靈」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰武靈王使惠文王蒞政李兌為相武靈王不以身躬親殺」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生之柄，故劫於李兌」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-42\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 42,\n      \"canonicalText\": \"說五\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-42_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說五。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「說五」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「五」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說五」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-43\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 43,\n      \"canonicalText\": \"茲鄭子引輦上高梁而不能支。茲鄭踞轅而歌，前者止，後者趨，輦乃上。使茲鄭無術以致人，則身雖絕力至死，輦猶不上也。今身不至勞苦而輦以上者，有術以致人之故也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-43_s-1\",\n        \"han-fei-zi_ch-35_p-43_s-2\",\n        \"han-fei-zi_ch-35_p-43_s-3\",\n        \"han-fei-zi_ch-35_p-43_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"茲鄭子引輦上高梁而且不能支。茲鄭踞轅而且歌，前的人或事止，後的人或事趨，輦乃上。使茲鄭無督察權術以致人，則身雖絕力至死，輦猶不上啊。今身不至勞苦而且輦以上的人或事，有督察權術以致人的所以啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「茲鄭子引輦上高梁而不能支」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「茲」、「鄭」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「茲鄭子引輦上高梁而不能支茲鄭踞轅而歌前者止後者趨」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「茲鄭踞轅而歌，前者止，後者趨，輦乃上」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-44\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 44,\n      \"canonicalText\": \"趙簡主出稅者，吏請輕重，簡主曰：「勿輕勿重。重則利入於上，若輕則利歸於民，吏無私利而正矣。」薄疑謂趙簡主曰：「君之國中飽。」簡主欣然而喜曰：「何如焉？」對曰：「府庫空虛於上，百姓貧餓於下，然而姦吏富矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-44_s-1\",\n        \"han-fei-zi_ch-35_p-44_s-2\",\n        \"han-fei-zi_ch-35_p-44_s-3\",\n        \"han-fei-zi_ch-35_p-44_s-4\",\n        \"han-fei-zi_ch-35_p-44_s-5\",\n        \"han-fei-zi_ch-35_p-44_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"趙簡主出稅的人或事，吏請輕重，簡主說道：勿輕勿重。重則利入於上，若輕則利歸於民，吏無私利而且正矣。薄疑謂趙簡主說道：國君的國中飽。簡主欣然而且喜說道：何如焉？對說道：府庫空虛於上，百姓貧餓於下，然而且姦吏富矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「趙簡主出稅者，吏請輕重，簡主曰：「勿輕勿重」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「趙」、「簡」、「主」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「趙簡主出稅者吏請輕重簡主曰勿輕勿重重則利入於上若」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「重則利入於上，若輕則利歸於民，吏無私利而正矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-45\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 45,\n      \"canonicalText\": \"齊桓公微服以巡民家，人有年老而自養者，桓公問其故，對曰：「臣有子三人，家貧，無以妻之，傭未反。」桓公歸，以告管仲，管仲曰：「畜積有腐棄之財則人飢餓，宮中有怨女則民無妻。」桓公曰：「善。」乃論宮中有婦人而嫁之，下令於民曰：「丈夫二十而室，婦人十五而嫁。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-45_s-1\",\n        \"han-fei-zi_ch-35_p-45_s-2\",\n        \"han-fei-zi_ch-35_p-45_s-3\",\n        \"han-fei-zi_ch-35_p-45_s-4\",\n        \"han-fei-zi_ch-35_p-45_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊桓公微服以巡民家，人有年老而且自養的人或事，桓公問他的所以，對說道：臣屬有子三人，家貧，無以妻的，傭未反。桓公歸，以告管仲，管仲說道：畜積有腐棄的財則人飢餓，宮中有怨女則民無妻。桓公說道：善。乃論宮中有婦人而且嫁的，下令於民說道：丈夫二十而且室，婦人十五而且嫁。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「齊桓公微服以巡民家，人有年老而自養者，桓公問其故，對曰：「臣有子三人，家貧，無以妻之，傭未反」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「齊」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「齊桓公微服以巡民家人有年老而自養者桓公問其故對曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」桓公歸，以告管仲，管仲曰：「畜積有腐棄之財則人飢餓，宮中有怨女則民無妻」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 46,\n      \"canonicalText\": \"一曰。桓公微服而行於民間，有鹿門稷者，行年七十而無妻，桓公問管仲曰：「有民老而無妻者乎？」管仲曰：「有鹿門稷者，行年七十矣而無妻」桓公曰：「何以令之有妻？」管仲曰：「臣聞之，上有積財則民臣必匱乏於下，宮中有怨女則有老而無妻者。」桓公曰：「善。」令於宮中女子未嘗御出嫁之，乃令男子年二十而室，女年十五而嫁。則內無怨女，外無曠夫。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-46_s-1\",\n        \"han-fei-zi_ch-35_p-46_s-2\",\n        \"han-fei-zi_ch-35_p-46_s-3\",\n        \"han-fei-zi_ch-35_p-46_s-4\",\n        \"han-fei-zi_ch-35_p-46_s-5\",\n        \"han-fei-zi_ch-35_p-46_s-6\",\n        \"han-fei-zi_ch-35_p-46_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。桓公微服而且行於民間，有鹿門稷的人或事，行年七十而且無妻，桓公問管仲說道：有民老而且無妻的人或事乎？管仲說道：有鹿門稷的人或事，行年七十矣而且無妻桓公說道：何以令的有妻？管仲說道：臣屬聞的，上有積財則民臣屬必匱乏於下，宮中有怨女則有老而且無妻的人或事。桓公說道：善。令於宮中女子未嘗御出嫁的，乃令男子年二十而且室，女年十五而且嫁。則內無怨女，外無曠夫。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「桓公微服而行於民間，有鹿門稷者，行年七十而無妻，桓公問管仲曰：「有民老而無妻者乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰桓公微服而行於民間有鹿門稷者行年七十而無妻桓」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」管仲曰：「有鹿門稷者，行年七十矣而無妻」桓公曰：「何以令之有妻」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-47\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 47,\n      \"canonicalText\": \"延陵卓子乘蒼龍挑文之乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁之，欲退則錯錣貫之，馬因旁出。造父過而為之泣涕曰：「古之治人亦然矣。夫賞所以勸之而毀存焉，罰所以禁之而譽加焉，民中立而不知所由，此亦聖人之所為泣也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-47_s-1\",\n        \"han-fei-zi_ch-35_p-47_s-2\",\n        \"han-fei-zi_ch-35_p-47_s-3\",\n        \"han-fei-zi_ch-35_p-47_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"延陵卓子乘蒼龍挑文的乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁的，欲退則錯錣貫的，馬因旁出。造父過而且為的泣涕說道：古的治人亦然矣。夫賞賜所以勸的而且毀存焉，刑罰所以禁的而且譽加焉，民中立而且不知所由，此亦聖人的所為泣啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「延陵卓子乘蒼龍挑文之乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁之，欲退則錯錣貫之，馬因旁出」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「延」、「陵」、「卓」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「延陵卓子乘蒼龍挑文之乘鉤飾在前錯錣在後馬欲進則鉤」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「造父過而為之泣涕曰：「古之治人亦然矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-48\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"order\": 48,\n      \"canonicalText\": \"一曰。延陵卓子乘蒼龍與翟文之乘，前則有錯飾，後則有利錣，進則引之，退則筴之，馬前不得進，後不得退，遂避而逸，因下抽刀而刎其腳。造父見之、泣，終日不食，因仰天而歎曰：「筴所以進之也，錯飾在前；引所以退之也，利錣在後。今人主以其清潔也進之，以其不適左右也退之，以其公正也譽之，以其不聽從也廢之，民懼，中立而不知所由，此聖人之所為泣也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-35_p-48_s-1\",\n        \"han-fei-zi_ch-35_p-48_s-2\",\n        \"han-fei-zi_ch-35_p-48_s-3\",\n        \"han-fei-zi_ch-35_p-48_s-4\",\n        \"han-fei-zi_ch-35_p-48_s-5\",\n        \"han-fei-zi_ch-35_p-48_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。延陵卓子乘蒼龍與翟文的乘，前則有錯飾，後則有利錣，進則引的，退則筴的，馬前不得進，後不得退，遂避而且逸，因下抽刀而且刎他的腳。造父見的、泣，終日不食，因仰天而且歎說道：筴所以進的啊，錯飾在前；引所以退的啊，利錣在後。今人主以他的清潔啊進的，以他的不適左右啊退的，以他的公正啊譽的，以他的不聽從啊廢的，民懼，中立而且不知所由，此聖人的所為泣啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說右下〉。韓非深刻融合法、術、勢三大治國精要，此處「延陵卓子乘蒼龍與翟文之乘，前則有錯飾，後則有利錣，進則引之，退則筴之，馬前不得進，後不得退，遂避而逸，因下抽刀而刎其腳」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「延」、「陵」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰延陵卓子乘蒼龍與翟文之乘前則有錯飾後則有利錣」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「造父見之、泣，終日不食，因仰天而歎曰：「筴所以進之也，錯飾在前」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-35_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"一、賞罰共則禁令不行，何以明之，明之以造父、於期。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"子罕為出彘，田恆為圃池，故宋君、簡公弒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"患在王良、造父之共車，田連、成竅之共琴也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"二、治強生於法，弱亂生於阿，君明於此，則正賞罰而非仁下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"爵祿生於功，誅罰生於罪，臣明於此，則盡死力而非忠君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"君通於不仁，臣通於不忠，則可以王矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"昭襄知主情，而不發五苑；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"田鮪知臣情，故教田章；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"而公儀辭魚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"三、明主者、鑒於外也，而外事不得不成，故蘇代非齊王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"人主鑒於士也，而居者不適不顯，故潘壽言禹情。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"人主無所覺悟，方吾知之，故恐同衣於族，而況借於權乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"吳章知之，故說以佯，而況借於誠乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"趙王惡虎目而壅；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"明主之道，如周行人之卻衛侯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"四、人主者，守法責成以立功者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"聞有吏雖亂而有獨善之民，不聞有亂民而有獨治之吏，故明主治吏不治民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"說在搖木之本，與引網之綱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"故失火之嗇夫，不可不論也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"救火者，吏操壺走火、則一人之用也，操鞭使人、則役萬夫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"故所遇術者，如造父之遇驚馬，牽馬推車則不能進，代御執轡持筴則馬鹹騖矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"是以說在椎鍛平夷，榜檠矯直。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"不然，敗在淖齒用齊戮閔王，李兌用趙餓主父也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"五、因事之理則不勞而成，故茲鄭之踞轅而歌以上高梁也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"其患在趙簡主稅吏請輕重，薄疑之言國中飽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"簡主喜而府庫虛，百姓餓而姦吏富也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"故桓公巡民而管仲省腐財怨女。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"不然，則在延陵乘馬不得進，造父過之而為之泣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"右經\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"說一\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"造父御四馬，馳驟周旋而恣欲於馬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"恣欲於馬者，擅轡筴之制也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"然馬驚於出彘，而造父不能禁制者，非轡筴之嚴不足也，威分於出彘也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"王子於期為駙駕，轡筴不用而擇欲於馬，擅芻水之利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"然馬過於圃池而駙馬敗者，非芻水之利不足也，德分於圃池也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"故王良、造父，天下之善御者也，然而使王良操左革而叱吒之，使造父操右革而鞭笞之，馬不能行十里，共故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"田連、成竅，天下善鼓琴者也，然而田連鼓上，成竅擫下，而不能成曲，亦共故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"夫以王良、造父之巧，共轡而御不能使馬，人主安能與其臣共權以為治？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"以田連、成竅之巧，共琴而不能成曲，人主又安能與其臣共勢以成功乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池，去車走池，駕敗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"王子於期為趙簡主取道爭千里之表，其始發也，彘伏溝中，王子於期齊轡筴而進之，彘突出於溝中，馬驚駕敗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"司城子罕謂宋君曰：「慶賞賜與，民之所喜也，君自行之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"殺戮誅罰，民之所惡也，臣請當之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"」宋君曰：「諾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"」於是出威令，誅大臣，君曰「問子罕」也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"於是大臣畏之，細民歸之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"處期年，子罕殺宋君而奪政。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"故子罕為出彘以奪其君國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"簡公在上位，罰重而誅嚴，厚賦斂而殺戮民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"田成恆設慈愛，明寬厚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"簡公以齊民為渴馬，不以恩加民，而田成恆以仁厚為圃池也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"造父為齊王駙駕，以渴服馬，百日而服成，服成請效駕，齊王王曰：「效駕於圃中。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"」造父驅車入圃，馬見圃池而走，造父不能禁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-12_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"造父以渴服馬久矣，今馬見池，駻而走，雖造父不能治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-12_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"今簡公之以法禁其眾久矣，而田成恆利之，是田成恆傾圃池而示渴民也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"王子於期為宋君為千里之逐。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"已駕，察手吻文。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-13_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"且發矣，驅而前之，輪中繩引而卻之，馬掩跡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-13_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"拊而發之，彘逸出於竇中，馬退而卻，筴不能進前也，馬駻而走，轡不能正也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"司城子罕謂宋君曰：「慶賞賜予者，民之所好也，君自行之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"誅罰殺戮者，民之所惡也，臣請當之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"」於是戮細民而誅大臣，君曰「與子罕議之」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"居期年，民知殺生之命制於子罕也，故一國歸焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 6,\n      \"canonicalText\": \"故子罕劫宋君而奪其政，法不能禁也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 7,\n      \"canonicalText\": \"故曰子罕為出彘，而田成常為圃池也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 8,\n      \"canonicalText\": \"令王良、造父共車，人操一邊轡而入門閭，駕必敗而道不至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-14_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-14\",\n      \"order\": 9,\n      \"canonicalText\": \"令田連、成竅共琴，人撫一絃而揮，則音必敗曲不遂矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-15_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"說二\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"秦昭王有病，百姓裏買牛而家為王禱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"公孫述出見之，入賀王曰：「百姓乃皆裏買牛為王禱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"」王使人問之，果有之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"王曰：「訾之人二甲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"夫非令而擅禱，是愛寡人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"夫愛寡人，寡人亦且改法而心與之相循者，是法不立，法不立，亂亡之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"不如人罰二甲而復與為治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-16_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"秦襄王病，百姓為之禱，病癒，殺牛塞禱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"郎中閻遏、公孫衍出見之曰：「非社臘之時也，奚自殺牛而祠社？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"」怪而問之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"百姓曰：「人主病，為之禱，今病癒，殺牛塞禱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 6,\n      \"canonicalText\": \"」閻遏、公孫衍說，見王，拜賀曰：「過堯、舜矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 7,\n      \"canonicalText\": \"」王驚曰：「何謂也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 8,\n      \"canonicalText\": \"」對曰：「堯、舜，其民未至為之禱也，今王病，而民以牛禱，病癒，殺牛塞禱，故臣竊以王為過堯、舜也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 9,\n      \"canonicalText\": \"」王因使人問之何裏為之，訾其里正與伍老屯二甲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 10,\n      \"canonicalText\": \"閻遏、公孫衍媿不敢言。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 11,\n      \"canonicalText\": \"居數月，王飲酒酣樂，閻遏、公孫衍謂王曰：「前時臣竊以王為過堯、舜，非直敢諛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 12,\n      \"canonicalText\": \"堯、舜病，且其民未至為之禱也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 13,\n      \"canonicalText\": \"今王病而民以牛禱，病癒，殺牛塞禱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 14,\n      \"canonicalText\": \"今乃訾其里正與伍老屯二甲，臣竊怪之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 15,\n      \"canonicalText\": \"」王曰：「子何故不知於此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 16,\n      \"canonicalText\": \"彼民之所以為我用者，非以吾愛之為我用者也，以吾勢之為我用者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 17,\n      \"canonicalText\": \"吾釋勢與民相收，若是，吾適不愛，而民因不為我用也，故遂絕愛道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-17_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-17\",\n      \"order\": 18,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"秦大饑，應侯請曰：「五苑之草著、蔬菜、橡果、棗栗，足以活民，請發之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"」昭襄王曰：「吾秦法，使民有功而受賞，有罪而受誅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"今發五苑之蔬草者，使民有功與無功俱賞也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"夫使民有功與無功俱賞者，此亂之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"夫發五苑而亂，不如棄棗蔬而治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"」一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"「今發五苑之蓏蔬棗栗足以活民，是用民有功與無功爭取也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"夫生而亂，不如死而治，大夫其釋之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-18_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-18\",\n      \"order\": 9,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-19_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"田鮪教其子田章曰：「欲利而身，先利而君；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-19_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"欲富而家，先富而國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-19_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-20_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-20_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"田鮪教其子田章曰：「主賣官爵，臣賣智力，故自恃無恃人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-20_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-21_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"公儀休相魯而嗜魚，一國盡爭買魚而獻之，公儀子不受，其弟諫曰：「夫子嗜魚而不受者何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-21_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-21\",\n      \"order\": 2,\n      \"canonicalText\": \"」對曰：「夫唯嗜魚，故不受也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-21_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-21\",\n      \"order\": 3,\n      \"canonicalText\": \"夫即受魚，必有下人之色，有下人之色，將枉於法，枉於法則免於相，雖嗜魚，此不必能自給致我魚，我又不能自給魚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-21_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-21\",\n      \"order\": 4,\n      \"canonicalText\": \"即無受魚而不免於相，雖嗜魚，我能長自給魚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-21_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-21\",\n      \"order\": 5,\n      \"canonicalText\": \"」此明夫恃人不如自恃也，明於人之為己者不如己之自為也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-22_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"說三\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"子之相燕，貴而主斷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"蘇代為齊使燕，王問之曰：「齊王亦何如主也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 3,\n      \"canonicalText\": \"」對曰：「必不霸矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 4,\n      \"canonicalText\": \"」燕王曰：「何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 5,\n      \"canonicalText\": \"」對曰：「昔桓公之霸也，內事屬鮑叔，外事屬管仲，桓公被髮而御婦人，日遊於市。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 6,\n      \"canonicalText\": \"今齊王不信其大臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 7,\n      \"canonicalText\": \"」於是燕王因益大信子之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-23_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-23\",\n      \"order\": 8,\n      \"canonicalText\": \"子之聞之，使人遺蘇代金百鎰，而聽其所使之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 2,\n      \"canonicalText\": \"蘇代為秦使燕，見無益子之，則必不得事而還，貢賜又不出，於是見燕王乃譽齊王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 3,\n      \"canonicalText\": \"燕王曰：「齊王何若是之賢也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 4,\n      \"canonicalText\": \"則將必王乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 5,\n      \"canonicalText\": \"」蘇代曰：「救亡不暇，安得王哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 6,\n      \"canonicalText\": \"」燕王曰：「何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 7,\n      \"canonicalText\": \"」曰：「其任所愛不均。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 8,\n      \"canonicalText\": \"」燕王曰：「其亡何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 9,\n      \"canonicalText\": \"」曰：「昔者齊桓公愛管仲，置以為仲父，內事理焉，外事斷焉，舉國而歸之，故一匡天下，九合諸侯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 10,\n      \"canonicalText\": \"今齊任所愛不均，是以知其亡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 11,\n      \"canonicalText\": \"」燕王曰：「今吾任子之，天下未之聞也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-24_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-24\",\n      \"order\": 12,\n      \"canonicalText\": \"」於是明日張朝而聽子之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-25_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-25\",\n      \"order\": 1,\n      \"canonicalText\": \"潘壽謂燕王曰：「王不如以國讓子之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-25_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-25\",\n      \"order\": 2,\n      \"canonicalText\": \"人所以謂堯賢者，以其讓天下於許由，許由必不受也，則是堯有讓許由之名而實不失天下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-25_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-25\",\n      \"order\": 3,\n      \"canonicalText\": \"今王以國讓子之，子之必不受也，則是王有讓子之之名而與堯同行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-25_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-25\",\n      \"order\": 4,\n      \"canonicalText\": \"」於是燕王因舉國而屬之，子之大重。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 2,\n      \"canonicalText\": \"潘壽，闞者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 3,\n      \"canonicalText\": \"燕使人聘之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 4,\n      \"canonicalText\": \"潘壽見燕王曰：「臣恐子之之如益也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 5,\n      \"canonicalText\": \"」王曰：「何益哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 6,\n      \"canonicalText\": \"」對曰：「古者禹死，將傳天下於益，啟之人因相與攻益而立啟。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 7,\n      \"canonicalText\": \"今王信愛子之，將傳國子之，太子之人盡懷印為，子之之人無一人在朝廷者，王不幸棄群臣，則子之亦益也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-26_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-26\",\n      \"order\": 8,\n      \"canonicalText\": \"」王因收吏璽自三百石以上皆效之子之，子之大重。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-27_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-27\",\n      \"order\": 1,\n      \"canonicalText\": \"夫人主之所以鏡照者，諸侯之士徒也，今諸侯之士徒皆私門之黨也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-27_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-27\",\n      \"order\": 2,\n      \"canonicalText\": \"人主之所以自淺娟者，巖穴之士徒也，今巖穴之士徒皆私門之舍人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-27_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-27\",\n      \"order\": 3,\n      \"canonicalText\": \"是何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-27_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-27\",\n      \"order\": 4,\n      \"canonicalText\": \"奪褫之資在子之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-27_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-27\",\n      \"order\": 5,\n      \"canonicalText\": \"故吳章曰：「人主不佯憎愛人，佯愛人不得復憎也，佯憎人不得復愛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-27_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-27\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 2,\n      \"canonicalText\": \"燕王欲傳國於子之也，問之潘壽，對曰：「禹愛益，而任天下於益，已而以啟人為吏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 3,\n      \"canonicalText\": \"及老，而以啟為不足任天下，故傳天下於益，而勢重盡在啟也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 4,\n      \"canonicalText\": \"已而啟與友黨攻益而奪之天下，是禹名傳天下於益，而實令啟自取之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 5,\n      \"canonicalText\": \"此禹之不及堯、舜明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 6,\n      \"canonicalText\": \"今王欲傳之子之，而吏無非太子之人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 7,\n      \"canonicalText\": \"是名傳之，而實令太子自取之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-28_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-28\",\n      \"order\": 8,\n      \"canonicalText\": \"」燕王乃收璽自三百石以上皆效之子之，子之遂重。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-29_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-29\",\n      \"order\": 1,\n      \"canonicalText\": \"方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者共家，而況君人者乃借其權而外其勢乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-29_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-29\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-30_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-30\",\n      \"order\": 1,\n      \"canonicalText\": \"吳章謂韓宣王曰：「人主不可佯愛人，一日不可復憎；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-30_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-30\",\n      \"order\": 2,\n      \"canonicalText\": \"不可以佯憎人，一日不可復愛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-30_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-30\",\n      \"order\": 3,\n      \"canonicalText\": \"故佯憎佯愛之徵見，則諛者因資而毀譽之，雖有明主不能復收，而況於以誠借人也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-30_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-30\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-31_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-31\",\n      \"order\": 1,\n      \"canonicalText\": \"趙王遊於圃中，左右以菟與虎而輟，盼然環其眼，王曰：「可惡哉，虎目也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-31_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-31\",\n      \"order\": 2,\n      \"canonicalText\": \"」左右曰：「平陽君之目可惡過此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-31_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-31\",\n      \"order\": 3,\n      \"canonicalText\": \"見此未有害也，見平陽君之目如此者則必死矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-31_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-31\",\n      \"order\": 4,\n      \"canonicalText\": \"」其明日，平陽君聞之，使人殺言者，而王不誅也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-32_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-32\",\n      \"order\": 1,\n      \"canonicalText\": \"衛君入朝於周，周行人問其號，對曰：「諸侯闢疆。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-32_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-32\",\n      \"order\": 2,\n      \"canonicalText\": \"」周行人卻之曰：「諸侯不得與天子同號。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-32_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-32\",\n      \"order\": 3,\n      \"canonicalText\": \"」衛君乃自更曰「諸侯燬」而後內之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-32_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-32\",\n      \"order\": 4,\n      \"canonicalText\": \"仲尼聞之曰：「遠哉禁偪，虛名不以借人，況實事乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-32_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-32\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-33_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-33\",\n      \"order\": 1,\n      \"canonicalText\": \"說四\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-34_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-34\",\n      \"order\": 1,\n      \"canonicalText\": \"搖木者一一攝其葉則勞而不遍，左右拊其本而葉遍搖矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-34_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-34\",\n      \"order\": 2,\n      \"canonicalText\": \"臨淵而搖木，鳥驚而高，魚恐而下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-34_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-34\",\n      \"order\": 3,\n      \"canonicalText\": \"善張網者引其綱，不一一攝萬目而後得則是勞而難，引其綱而魚已囊矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-34_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-34\",\n      \"order\": 4,\n      \"canonicalText\": \"故吏者，民之本綱者也，故聖人治吏不治民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-35_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-35\",\n      \"order\": 1,\n      \"canonicalText\": \"救火者，令吏挈壺甕而走火則一人之用也，操鞭箠指麾而趣使人則制萬夫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-35_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-35\",\n      \"order\": 2,\n      \"canonicalText\": \"是以聖人不親細民，明主不躬小事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-36_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-36\",\n      \"order\": 1,\n      \"canonicalText\": \"造父方耨，得有子父乘車過者，馬驚而不行，其子下車牽馬，父子推車請造父助我推車，造父因收器輟而寄載之，援其子之乘，乃始檢轡持筴，未之用也而馬轡驚矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-36_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-36\",\n      \"order\": 2,\n      \"canonicalText\": \"使造父而不能御，雖盡力勞身助之推車，馬猶不肯行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-36_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-36\",\n      \"order\": 3,\n      \"canonicalText\": \"今身使佚，且寄載，有德於人者，有術而御之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-36_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-36\",\n      \"order\": 4,\n      \"canonicalText\": \"故國者君之車也，勢者君之馬也，無術以御之，身雖勞猶不免亂，有術以御之，身處佚樂之地，又致帝王之功也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-37_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-37\",\n      \"order\": 1,\n      \"canonicalText\": \"椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也，所以平不夷矯不直也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-38_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-38\",\n      \"order\": 1,\n      \"canonicalText\": \"淖齒之用齊也擢閔王之筋，李兌之用趙也餓殺主父。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-38_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-38\",\n      \"order\": 2,\n      \"canonicalText\": \"此二君者皆不能用其椎鍛榜檠，故身死為戮而為天下笑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-39_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-39\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-39_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-39\",\n      \"order\": 2,\n      \"canonicalText\": \"入齊則獨聞淖齒而不聞齊王，入趙則獨聞李兌而不聞趙王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-39_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-39\",\n      \"order\": 3,\n      \"canonicalText\": \"故曰：人主者不操術，則威勢輕而臣擅名。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 2,\n      \"canonicalText\": \"田嬰相齊，人有說王者曰：「終歲之計，王不一以數日之間自聽之，則無以知吏之姦邪得失也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 3,\n      \"canonicalText\": \"」王曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 4,\n      \"canonicalText\": \"」田嬰聞之，即遽請於王而聽其計，王將聽之矣，田嬰令官具押券鬥石參升之計，王自聽計，計不勝聽，罷食，後復坐，不復暮食矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 5,\n      \"canonicalText\": \"田嬰復謂曰：「群臣所終歲日夜不敢偷怠之事也，王以一夕聽之，則群臣有為勸勉矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 6,\n      \"canonicalText\": \"」王曰：「諾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 7,\n      \"canonicalText\": \"」俄而王已睡矣，吏盡揄刀削其押券升石之計。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-40_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-40\",\n      \"order\": 8,\n      \"canonicalText\": \"王自聽之，亂乃始生。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-41_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-41\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-41_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-41\",\n      \"order\": 2,\n      \"canonicalText\": \"武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生之柄，故劫於李兌。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-42_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-42\",\n      \"order\": 1,\n      \"canonicalText\": \"說五\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-43_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-43\",\n      \"order\": 1,\n      \"canonicalText\": \"茲鄭子引輦上高梁而不能支。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-43_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-43\",\n      \"order\": 2,\n      \"canonicalText\": \"茲鄭踞轅而歌，前者止，後者趨，輦乃上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-43_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-43\",\n      \"order\": 3,\n      \"canonicalText\": \"使茲鄭無術以致人，則身雖絕力至死，輦猶不上也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-43_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-43\",\n      \"order\": 4,\n      \"canonicalText\": \"今身不至勞苦而輦以上者，有術以致人之故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-44_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-44\",\n      \"order\": 1,\n      \"canonicalText\": \"趙簡主出稅者，吏請輕重，簡主曰：「勿輕勿重。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-44_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-44\",\n      \"order\": 2,\n      \"canonicalText\": \"重則利入於上，若輕則利歸於民，吏無私利而正矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-44_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-44\",\n      \"order\": 3,\n      \"canonicalText\": \"」薄疑謂趙簡主曰：「君之國中飽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-44_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-44\",\n      \"order\": 4,\n      \"canonicalText\": \"」簡主欣然而喜曰：「何如焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-44_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-44\",\n      \"order\": 5,\n      \"canonicalText\": \"」對曰：「府庫空虛於上，百姓貧餓於下，然而姦吏富矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-44_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-44\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-45_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-45\",\n      \"order\": 1,\n      \"canonicalText\": \"齊桓公微服以巡民家，人有年老而自養者，桓公問其故，對曰：「臣有子三人，家貧，無以妻之，傭未反。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-45_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-45\",\n      \"order\": 2,\n      \"canonicalText\": \"」桓公歸，以告管仲，管仲曰：「畜積有腐棄之財則人飢餓，宮中有怨女則民無妻。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-45_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-45\",\n      \"order\": 3,\n      \"canonicalText\": \"」桓公曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-45_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-45\",\n      \"order\": 4,\n      \"canonicalText\": \"」乃論宮中有婦人而嫁之，下令於民曰：「丈夫二十而室，婦人十五而嫁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-45_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-45\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-46\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-46\",\n      \"order\": 2,\n      \"canonicalText\": \"桓公微服而行於民間，有鹿門稷者，行年七十而無妻，桓公問管仲曰：「有民老而無妻者乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-46\",\n      \"order\": 3,\n      \"canonicalText\": \"」管仲曰：「有鹿門稷者，行年七十矣而無妻」桓公曰：「何以令之有妻？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-46\",\n      \"order\": 4,\n      \"canonicalText\": \"」管仲曰：「臣聞之，上有積財則民臣必匱乏於下，宮中有怨女則有老而無妻者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-46\",\n      \"order\": 5,\n      \"canonicalText\": \"」桓公曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-46\",\n      \"order\": 6,\n      \"canonicalText\": \"」令於宮中女子未嘗御出嫁之，乃令男子年二十而室，女年十五而嫁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-46_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-46\",\n      \"order\": 7,\n      \"canonicalText\": \"則內無怨女，外無曠夫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-47_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-47\",\n      \"order\": 1,\n      \"canonicalText\": \"延陵卓子乘蒼龍挑文之乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁之，欲退則錯錣貫之，馬因旁出。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-47_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-47\",\n      \"order\": 2,\n      \"canonicalText\": \"造父過而為之泣涕曰：「古之治人亦然矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-47_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-47\",\n      \"order\": 3,\n      \"canonicalText\": \"夫賞所以勸之而毀存焉，罰所以禁之而譽加焉，民中立而不知所由，此亦聖人之所為泣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-47_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-47\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-48_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-48\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-48_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-48\",\n      \"order\": 2,\n      \"canonicalText\": \"延陵卓子乘蒼龍與翟文之乘，前則有錯飾，後則有利錣，進則引之，退則筴之，馬前不得進，後不得退，遂避而逸，因下抽刀而刎其腳。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-48_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-48\",\n      \"order\": 3,\n      \"canonicalText\": \"造父見之、泣，終日不食，因仰天而歎曰：「筴所以進之也，錯飾在前；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-48_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-48\",\n      \"order\": 4,\n      \"canonicalText\": \"引所以退之也，利錣在後。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-48_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-48\",\n      \"order\": 5,\n      \"canonicalText\": \"今人主以其清潔也進之，以其不適左右也退之，以其公正也譽之，以其不聽從也廢之，民懼，中立而不知所由，此聖人之所為泣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-35_p-48_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-35\",\n      \"passageId\": \"han-fei-zi_ch-35_p-48\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
